param()
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot; $input = Join-Path $root 'input'; $out = Join-Path $root 'outputs'
New-Item -ItemType Directory -Force -Path (Join-Path $out 'reports'),(Join-Path $out 'low-attendance') | Out-Null
Add-Type -AssemblyName System.IO.Compression.FileSystem
function Read-XlsxRows($path) {
  $zip=[System.IO.Compression.ZipFile]::OpenRead($path); try { $entry=$zip.GetEntry('xl/worksheets/sheet1.xml'); if($null -eq $entry){throw "Missing sheet1.xml"}; $sr=[IO.StreamReader]::new($entry.Open()); $xml=[xml]$sr.ReadToEnd(); $sr.Dispose(); $result=@(); foreach($row in $xml.worksheet.sheetData.row){$vals=@(); foreach($cell in $row.c){if($cell.t -eq 'inlineStr'){$vals += [string]$cell.is.t}else{$vals += [string]$cell.v}}; $result += ,$vals}; return $result } finally {$zip.Dispose()} }
function XmlEscape([string]$s) { [System.Security.SecurityElement]::Escape($s) }
function New-SheetXml($rows) { $r=1; $x='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'; foreach($row in $rows){$x+="<row r='$r'>";$c=1;foreach($v in $row){$ref=[char](64+$c)+$r;if($v -is [int] -or $v -is [double] -or $v -is [decimal]){$x+="<c r='$ref'><v>$v</v></c>"}else{$x+="<c r='$ref' t='inlineStr'><is><t>$(XmlEscape ([string]$v))</t></is></c>"};$c++};$x+='</row>';$r++};return $x+'</sheetData></worksheet>' }
function Write-ZipText($path,$entries){if(Test-Path $path){Remove-Item $path -Force};$fs=[IO.File]::Open($path,[IO.FileMode]::Create);$zip=[IO.Compression.ZipArchive]::new($fs,[IO.Compression.ZipArchiveMode]::Create);foreach($key in $entries.Keys){$e=$zip.CreateEntry($key);$sw=[IO.StreamWriter]::new($e.Open(),[Text.UTF8Encoding]::new($false));$sw.Write([string]$entries[$key]);$sw.Dispose()};$zip.Dispose();$fs.Dispose()}
function New-ReportXlsx($path,$all,$low){$e=[ordered]@{};$e['[Content_Types].xml']='<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>';$e['_rels/.rels']='<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>';$e['xl/workbook.xml']='<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="All Students" sheetId="1" r:id="rId1"/><sheet name="Low Attendance" sheetId="2" r:id="rId2"/></sheets></workbook>';$e['xl/_rels/workbook.xml.rels']='<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/></Relationships>';$e['xl/worksheets/sheet1.xml']=New-SheetXml $all;$e['xl/worksheets/sheet2.xml']=New-SheetXml $low;Write-ZipText $path $e}
try {
  $summary=@(); $index=1
  foreach($book in Get-ChildItem $input -Filter 'attendance_dataset_*.xlsx' | Sort-Object Name) {
    $rows=Read-XlsxRows $book.FullName; if($rows.Count -lt 2){throw "No data rows in $($book.Name)"}; $headers=$rows[0]; $items=@()
    foreach($row in $rows[1..($rows.Count-1)]){$total=[int]$row[2];$attended=[int]$row[3];$pct= if($total -eq 0){0}else{[math]::Round(($attended*100.0/$total),2)};$items += [pscustomobject]@{StudentId=$row[0];Name=$row[1];TotalClasses=$total;AttendedClasses=$attended;AttendancePercentage=$pct;Status=if($pct -lt 75){'Low Attendance'}else{'Meets Threshold'}}}
    $sorted=@($items|Sort-Object AttendancePercentage,Name);$low=@($sorted|Where-Object{$_.AttendancePercentage -lt 75});$outRows=@();$outRows+=,@('StudentId','Name','TotalClasses','AttendedClasses','AttendancePercentage','Status');foreach($i in $sorted){$outRows+=,@($i.StudentId,$i.Name,$i.TotalClasses,$i.AttendedClasses,$i.AttendancePercentage,$i.Status)};$lowRows=@();$lowRows+=,@('StudentId','Name','TotalClasses','AttendedClasses','AttendancePercentage','Status');foreach($i in $low){$lowRows+=,@($i.StudentId,$i.Name,$i.TotalClasses,$i.AttendedClasses,$i.AttendancePercentage,$i.Status)}
    $stem=$book.BaseName;New-ReportXlsx (Join-Path $out "reports\${stem}_report.xlsx") $outRows $lowRows;$low|Export-Csv (Join-Path $out "low-attendance\${stem}_low.csv") -NoTypeInformation
    $summary += [pscustomobject]@{Dataset=$book.Name;TotalStudents=$sorted.Count;Below75=$low.Count;Report="reports\${stem}_report.xlsx";LowAttendanceCsv="low-attendance\${stem}_low.csv"};$index++
  }
  $summary|ConvertTo-Json -Depth 4|Set-Content (Join-Path $out 'summary.json') -Encoding UTF8
  if($summary.Count -ne 2){throw "Expected two datasets, found $($summary.Count)"}
  Write-Output "Processed $($summary.Count) attendance workbooks; outputs verified."
} catch { $_ | Out-String | Set-Content (Join-Path $out 'error.log'); throw }
